pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 depositAmount, uint256 cashOutAmount, address caller) public {
        vm.assume(caller != address(0));
        vm.assume(depositAmount > 1 ether && depositAmount <= 1000 ether);
        vm.assume(cashOutAmount <= 1000 ether);

        // Setup: fund and deposit
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        uint256 contractBalBefore = address(c).balance;
        uint256 callerBalanceBefore = c.balances(caller);

        // CashOut
        if (cashOutAmount <= callerBalanceBefore && cashOutAmount > 0) {
            vm.prank(caller);
            try c.CashOut(cashOutAmount) {
                uint256 contractBalAfter = address(c).balance;
                uint256 callerBalanceAfter = c.balances(caller);
                assertTrue(contractBalBefore - contractBalAfter == cashOutAmount && callerBalanceBefore - callerBalanceAfter == cashOutAmount);
            } catch {
                // If it reverts unexpectedly, balances should remain unchanged
                assertTrue(address(c).balance == contractBalBefore && c.balances(caller) == callerBalanceBefore);
            }
        } else {
            // If cashOutAmount exceeds balance, CashOut should not change state
            uint256 contractBalBeforeNoop = address(c).balance;
            vm.prank(caller);
            try c.CashOut(cashOutAmount) { } catch { }
            assertTrue(address(c).balance == contractBalBeforeNoop && c.balances(caller) == callerBalanceBefore);
        }
    }
}

